{"command":"cat > /workspace/compose.py << 'PYEOF'
import json
import subprocess
import time

def ft2_call(name, args):
    cmd = ['ft2', 'call', name, json.dumps(args)]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print("ERR", name, result.stderr[:200])
    return result.stdout.strip()

NOTE_MAP = {
    'C-': 0, 'C#': 1, 'D-': 2, 'D#': 3, 'E-': 4, 'F-': 5,
    'F#': 6, 'G-': 7, 'G#': 8, 'A-': 9, 'A#': 10, 'B-': 11
}

def note_to_num(note, octave):
    if note == '---' or note == '':
        return 0
    return (octave - 1) * 12 + NOTE_MAP[note] + 1

def set_cell(pat, row, ch, note='', inst=0, vol=64, eff=0, param=0):
    nnum = note_to_num(note, 4) if note and note[0] != '-' else 0
    if note and '-' in note and len(note) > 2:
        n = note[:2]
        o = int(note[2])
        nnum = note_to_num(n, o)
    args = {
        'pattern': pat,
        'row': row,
        'channel': ch,
        'note': nnum if nnum else '',
        'instrument': inst if inst else 0,
        'volume': vol if vol != 64 else 0,
        'effect': eff,
        'effect_param': param
    }
    if nnum == 0:
        args['note'] = 0
    ft2_call('pattern_set_cell', args)

def clear_pattern(pat):
    ft2_call('pattern_clear', {'pattern': pat})

# Set up patterns
print("Setting up patterns...")

# First, ensure patterns 0-7 exist with 64 rows
for p in range(8):
    ft2_call('pattern_set_length', {'pattern': p, 'rows': 64})

# Clear all
for p in range(8):
    clear_pattern(p)

# Define the tune in C minor
# Chords: Cm (C Eb G), Fm (F Ab C), G (G B D), Ab (Ab C Eb)

# Pattern 0: Intro - drums + simple bass
print("Pattern 0: Intro")
for row in range(64):
    # Kick on 1 and 5 every 8
    if row % 8 == 0:
        set_cell(0, row, 0, 'C-4', 1, vol=60)  # kick
    if row % 8 == 4:
        set_cell(0, row, 1, 'C-4', 2, vol=55)  # snare-ish on offbeats for variety

    # Hats
    if row % 4 == 2:
        set_cell(0, row, 2, 'C-5', 3, vol=35)

    # Simple bass line: C G Ab F
    bass_notes = ['C-3', 'G-2', 'G#2', 'F-2']
    if row % 16 == 0:
        set_cell(0, row, 3, bass_notes[0], 5, vol=48)
    elif row % 16 == 4:
        set_cell(0, row, 3, bass_notes[1], 5, vol=45)
    elif row % 16 == 8:
        set_cell(0, row, 3, bass_notes[2], 5, vol=46)
    elif row % 16 == 12:
        set_cell(0, row, 3, bass_notes[3], 5, vol=44)

# Pattern 1: Main theme A - melody + drums + bass
print("Pattern 1: Main A")
melody1 = [
    (0, 'C-5'), (4, 'Eb5'), (8, 'G-5'), (12, 'C-6'),
    (16, 'Bb5'), (20, 'G-5'), (24, 'Eb5'), (28, 'F-5'),
    (32, 'G-5'), (36, 'Ab5'), (40, 'Bb5'), (44, 'C-6'),
    (48, 'Eb6'), (52, 'D-6'), (56, 'C-6'), (60, 'Bb5'),
]
bass1 = [
    (0, 'C-3'), (8, 'G-2'), (16, 'Ab-2'), (24, 'Bb-2'),
    (32, 'C-3'), (40, 'G-2'), (48, 'F-2'), (56, 'G-2'),
]

for row in range(64):
    # Drums
    if row % 8 == 0:
        set_cell(1, row, 0, 'C-4', 1, vol=62)
    if row % 8 == 4:
        set_cell(1, row, 1, 'C-4', 2, vol=58)
    if row % 4 == 2:
        set_cell(1, row, 2, 'C-5', 3, vol=40)
    if row % 16 == 14:
        set_cell(1, row, 2, 'C-5', 4, vol=45)  # open hat

    # Bass
    for r, n in bass1:
        if row == r:
            set_cell(1, row, 3, n, 5, vol=50)

    # Melody lead
    for r, n in melody1:
        if row == r:
            set_cell(1, row, 4, n, 6, vol=55)

# Pattern 2: Arp variation
print("Pattern 2: Arp")
arp_notes = ['C-5', 'Eb5', 'G-5', 'C-6', 'Eb6', 'G-6', 'C-6', 'G-5']
for row in range(64):
    # Keep drums
    if row % 8 == 0:
        set_cell(2, row, 0, 'C-4', 1, vol=60)
    if row % 8 == 4:
        set_cell(2, row, 1, 'C-4', 2, vol=55)
    if row % 4 == 0:
        set_cell(2, row, 2, 'C-5', 3, vol=38)

    # Bass variation
    if row % 8 == 0:
        set_cell(2, row, 3, 'C-3', 5, vol=48)
    elif row % 8 == 4:
        set_cell(2, row, 3, 'Eb-3', 5, vol=46)

    # Fast arp on channel 5
    arp_row = row % 8
    set_cell(2, row, 5, arp_notes[arp_row], 8, vol=42)

    # Chord stabs
    if row % 16 == 0:
        set_cell(2, row, 6, 'G-4', 7, vol=35)
    if row % 16 == 8:
        set_cell(2, row, 6, 'Bb-4', 7, vol=35)

# Pattern 3: Build up / bridge
print("Pattern 3: Bridge")
for row in range(64):
    if row % 8 == 0:
        set_cell(3, row, 0, 'C-4', 1, vol=64)
    if row % 8 == 4:
        set_cell(3, row, 1, 'C-4', 2, vol=60)
    if row % 4 == 2:
        set_cell(3, row, 2, 'C-5', 3, vol=42)

    # Rising bass
    if row < 32:
        if row % 4 == 0:
            set_cell(3, row, 3, 'C-3', 5, vol=50)
    else:
        if row % 4 == 0:
            set_cell(3, row, 3, 'G-3', 5, vol=52)

    # High lead
    if row % 4 == 0:
        set_cell(3, row, 4, 'Eb-6', 6, vol=48)
    if row % 8 == 4:
        set_cell(3, row, 4, 'G-6', 6, vol=50)

# Pattern 4: Main theme B (variation with higher energy)
print("Pattern 4: Main B")
melody2 = [
    (0, 'G-5'), (2, 'Ab5'), (4, 'Bb5'), (6, 'C-6'),
    (8, 'Eb6'), (12, 'D-6'), (16, 'C-6'), (20, 'Bb5'),
    (24, 'Ab5'), (28, 'G-5'), (32, 'F-5'), (36, 'Eb5'),
    (40, 'D-5'), (44, 'Eb5'), (48, 'F-5'), (52, 'G-5'),
    (56, 'Ab5'), (60, 'Bb5'),
]
for row in range(64):
    # More active drums
    if row % 4 == 0:
        set_cell(4, row, 0, 'C-4', 1, vol=62)
    if row % 8 == 4:
        set_cell(4, row, 1, 'C-4', 2, vol=58)
    if row % 2 == 0:
        set_cell(4, row, 2, 'C-5', 3, vol=36)

    # Bass
    if row % 8 == 0:
        set_cell(4, row, 3, 'C-3', 5, vol=50)
    elif row % 8 == 4:
        set_cell(4, row, 3, 'G-2', 5, vol=48)

    # Melody
    for r, n in melody2:
        if row == r:
            set_cell(4, row, 4, n, 6, vol=56)

    # Arp fill
    if row % 4 == 1:
        set_cell(4, row, 5, 'C-6', 8, vol=38)

# Pattern 5: Arp + chords focus
print("Pattern 5: Arp focus")
for row in range(64):
    if row % 8 == 0:
        set_cell(5, row, 0, 'C-4', 1, vol=58)
    if row % 8 == 4:
        set_cell(5, row, 1, 'C-4', 2, vol=52)

    # Bass
    if row % 16 == 0:
        set_cell(5, row, 3, 'Ab-2', 5, vol=45)
    elif row % 16 == 8:
        set_cell(5, row, 3, 'Bb-2', 5, vol=45)

    # Chords
    if row % 8 == 0:
        set_cell(5, row, 6, 'C-5', 7, vol=40)
    elif row % 8 == 4:
        set_cell(5, row, 6, 'Eb-5', 7, vol=40)

    # Arp
    arp = ['G-5','Bb5','Eb6','G-6','Bb6','G-6','Eb6','Bb5'][row % 8]
    set_cell(5, row, 5, arp, 8, vol=44)

# Pattern 6: Build to climax
print("Pattern 6: Climax build")
for row in range(64):
    if row % 4 == 0:
        set_cell(6, row, 0, 'C-4', 1, vol=64)
    if row % 8 == 4:
        set_cell(6, row, 1, 'C-4', 2, vol=60)
    if row % 2 == 0:
        set_cell(6, row, 2, 'C-5', 3, vol=45)

    if row % 4 == 0:
        set_cell(6, row, 3, 'C-3', 5, vol=52)

    # Double time melody
    if row % 2 == 0:
        n = ['C-6','Eb6','G-6','Bb6','C-7','Bb6','G-6','Eb6'][ (row//2) % 8 ]
        set_cell(6, row, 4, n, 6, vol=50)

    # Fast arp
    set_cell(6, row, 5, ['Eb-5','G-5','Bb-5','C-6'][row%4], 8, vol=42)

# Pattern 7: Outro / wind down for clean loop
print("Pattern 7: Outro")
for row in range(64):
    if row < 48:
        if row % 8 == 0:
            set_cell(7, row, 0, 'C-4', 1, vol=55)
        if row % 8 == 4:
            set_cell(7, row, 1, 'C-4', 2, vol=50)
        if row % 4 == 2:
            set_cell(7, row, 2, 'C-5', 3, vol=30)

        if row % 16 == 0:
            set_cell(7, row, 3, 'C-3', 5, vol=40)
    else:
        # fade out last 16 rows
        if row % 8 == 0:
            set_cell(7, row, 3, 'C-3', 5, vol=25)

# Set order list for looping structure
# Intro -> A -> Arp -> Bridge -> B -> ArpFocus -> Climax -> Outro -> back to A
print("Setting order...")
order = [0, 1, 2, 3, 4, 5, 6, 7, 1, 2, 4, 5]  # 12 positions, loop to 1
for i, p in enumerate(order):
    ft2_call('order_set', {'position': i, 'pattern': p})

ft2_call('song_set', {'length': len(order), 'loop_start': 1})

print("Composition done!")
